def main():
    prepared=[]
    for patch in PATCHES:
        path=Path(patch['path'])
        if path.is_symlink(): raise RuntimeError('Unexpected symlink')
        before=path.read_bytes()
        if hashlib.sha256(before).hexdigest()!=patch['before']: raise RuntimeError('Source changed: '+str(path))
        after=before
        for start,stop,replacement in reversed(patch['edits']): after=after[:start]+replacement.encode()+after[stop:]
        if hashlib.sha256(after).hexdigest()!=patch['after']: raise RuntimeError('Output mismatch: '+str(path))
        if path.suffix=='.py': compile(after,str(path),'exec')
        prepared.append((path,after))
    for path,data in prepared: path.write_bytes(data)
    output=Path('postmatch-evidence');output.mkdir(exist_ok=True)
    (output/'source-hashes.json').write_text(json.dumps([{k:v for k,v in p.items() if k!='edits'} for p in PATCHES],indent=2))
if __name__=='__main__': main()
